<script setup lang="ts">
type Route='airborne'|'contact'|'food_water'|'vector'|'zoonotic'
type Intervention={id:string;nl:string;en:string;routes:Route[];effect:number;speed:number;burden:number;equity:number;evidence:number;kind:string}
const props=withDefaults(defineProps<{locale?:'nl'|'en'}>(),{locale:'nl'})
const nl=computed(()=>props.locale==='nl')
const p=reactive({route:'airborne' as Route,r0:2.5,presymptomatic:35,severity:45,icuNeed:25,capacityPressure:55,diagnostics:true,vaccine:false,treatment:false,uncertainty:55,lives:30,capacity:30,transmission:20,society:20})
const routes:{id:Route;nl:string;en:string}[]=[{id:'airborne',nl:'Lucht/respiratoir',en:'Airborne/respiratory'},{id:'contact',nl:'Direct contact',en:'Direct contact'},{id:'food_water',nl:'Voedsel/water',en:'Food/water'},{id:'vector',nl:'Vector',en:'Vector-borne'},{id:'zoonotic',nl:'Dier/omgeving',en:'Animal/environment'}]
const interventions:Intervention[]=[
 {id:'ventilation',nl:'Ventilatie en filtratie',en:'Ventilation and filtration',routes:['airborne'],effect:4.3,speed:3,burden:1.4,equity:4,evidence:4,kind:'omgeving'},
 {id:'isolation',nl:'Testen en casusisolatie',en:'Testing and case isolation',routes:['airborne','contact','food_water'],effect:4,speed:4,burden:2.1,equity:2.7,evidence:4.2,kind:'opsporing'},
 {id:'tracing',nl:'Contactonderzoek',en:'Contact tracing',routes:['airborne','contact'],effect:3.7,speed:3,burden:2.7,equity:3,evidence:3.8,kind:'opsporing'},
 {id:'protection',nl:'Respiratoire of contactbescherming',en:'Respiratory or contact protection',routes:['airborne','contact','zoonotic'],effect:3.8,speed:4.5,burden:1.8,equity:3,evidence:3.8,kind:'persoonlijk'},
 {id:'vaccination',nl:'Vaccinatie',en:'Vaccination',routes:['airborne','contact','food_water','vector','zoonotic'],effect:4.7,speed:2,burden:2,equity:4,evidence:3.5,kind:'medisch'},
 {id:'treatment',nl:'Behandeling en profylaxe',en:'Treatment and prophylaxis',routes:['airborne','contact','food_water','vector','zoonotic'],effect:4.2,speed:3.5,burden:1.6,equity:3.5,evidence:3.6,kind:'medisch'},
 {id:'healthcare',nl:'Zorgcapaciteit en personeelsbescherming',en:'Healthcare capacity and staff protection',routes:['airborne','contact','food_water','vector','zoonotic'],effect:3.6,speed:2.2,burden:2.4,equity:4.2,evidence:4,kind:'zorg'},
 {id:'source',nl:'Bron-, dier- en omgevingscontrole',en:'Source, animal and environmental control',routes:['food_water','vector','zoonotic'],effect:4.6,speed:3.2,burden:2.2,equity:3.5,evidence:4,kind:'bron'},
 {id:'support',nl:'Thuisblijf- en inkomensondersteuning',en:'Stay-home and income support',routes:['airborne','contact'],effect:3.1,speed:3.5,burden:2.5,equity:4.8,evidence:3.2,kind:'ondersteuning'},
 {id:'temporary',nl:'Tijdelijke brede contactreductie',en:'Temporary broad contact reduction',routes:['airborne','contact'],effect:4.4,speed:4.5,burden:4.8,equity:1.8,evidence:3.2,kind:'sociaal'}]
const totalWeight=computed(()=>p.lives+p.capacity+p.transmission+p.society||1)
const weight=(key:'lives'|'capacity'|'transmission'|'society')=>p[key]/totalWeight.value
const ranked=computed(()=>interventions.map(item=>{
 const routeMatch=item.routes.includes(p.route)?1:.12
 const transmissionNeed=Math.min(1.4,.35+p.r0/5+(p.presymptomatic/100)*.35)
 const healthNeed=.35+p.severity/100+p.icuNeed/180+p.capacityPressure/180
 const availability=item.id==='vaccination'?(p.vaccine?1:.05):item.id==='treatment'?(p.treatment?1:.08):(item.id==='isolation'||item.id==='tracing')?(p.diagnostics?1:.28):1
 const presymPenalty=item.id==='tracing'||item.id==='isolation'?1-p.presymptomatic/180:1
 const capacityBoost=item.id==='healthcare'?1+p.capacityPressure/100:1
 const socialPenalty=item.burden*(.4+weight('society')*2.2)
 const benefit=item.effect*routeMatch*availability*presymPenalty*capacityBoost*(transmissionNeed*weight('transmission')+healthNeed*(weight('lives')+weight('capacity'))+item.equity/5*.25)
 const confidence=.55+item.evidence/10-(p.uncertainty/100)*.28
 const score=benefit*confidence-socialPenalty*.32+item.speed*.12
 const reasons:string[]=[]
 if(routeMatch===1)reasons.push(nl.value?'past bij de transmissieroute':'matches the transmission route')
 if(item.id==='tracing'&&p.presymptomatic>45)reasons.push(nl.value?'verliest waarde door veel vroege transmissie':'loses value with extensive early transmission')
 if(item.id==='healthcare'&&p.capacityPressure>65)reasons.push(nl.value?'stijgt door druk op de zorg':'rises with healthcare pressure')
 if((item.id==='vaccination'&&!p.vaccine)||(item.id==='treatment'&&!p.treatment))reasons.push(nl.value?'is nog niet beschikbaar':'is not yet available')
 if(item.id==='temporary')reasons.push(nl.value?'heeft een hoge maatschappelijke last':'has a high societal burden')
 return{...item,score,confidence:Math.max(.15,Math.min(.95,confidence)),reasons}
 }).sort((a,b)=>b.score-a.score))
const preset=(name:'respiratory'|'ebola'|'qfever'|'food')=>{Object.assign(p,name==='respiratory'?{route:'airborne',r0:3.2,presymptomatic:45,severity:38,icuNeed:28,capacityPressure:68,diagnostics:true,vaccine:false,treatment:false,uncertainty:62}:name==='ebola'?{route:'contact',r0:1.7,presymptomatic:0,severity:92,icuNeed:45,capacityPressure:48,diagnostics:true,vaccine:true,treatment:true,uncertainty:38}:name==='qfever'?{route:'zoonotic',r0:.4,presymptomatic:0,severity:22,icuNeed:5,capacityPressure:18,diagnostics:true,vaccine:false,treatment:true,uncertainty:45}:{route:'food_water',r0:2.1,presymptomatic:15,severity:18,icuNeed:3,capacityPressure:30,diagnostics:true,vaccine:false,treatment:false,uncertainty:35})}
const routeLabel=computed(()=>routes.find(x=>x.id===p.route)![nl.value?'nl':'en'])
</script>

<template>
 <section class="response-model" data-analytics-model="pathogen-response">
  <header><p class="eyebrow">{{nl?'SCENARIOVERKENNER':'SCENARIO EXPLORER'}}</p><h2>{{nl?'De ziekte bepaalt de gereedschapskist':'The pathogen shapes the toolbox'}}</h2><p>{{nl?'Bouw een hypothetisch ziekteprofiel en zie hoe kenmerken, doelen en onzekerheid de rangorde van interventies veranderen. De uitkomst is een illustratie van beslislogica, geen medisch of beleidsadvies.':'Build a hypothetical disease profile and see how characteristics, objectives and uncertainty change the intervention ranking. The result illustrates decision logic; it is not medical or policy advice.'}}</p></header>
  <div class="presets"><span>{{nl?'Startscenario':'Starting scenario'}}</span><button @click="preset('respiratory')">{{nl?'Nieuw respiratoir virus':'Novel respiratory virus'}}</button><button @click="preset('ebola')">Ebola-achtig</button><button @click="preset('qfever')">Q-koortsachtig</button><button @click="preset('food')">{{nl?'Voedseluitbraak':'Foodborne outbreak'}}</button></div>
  <div class="model-grid">
   <div class="controls">
    <section><h3>1 · {{nl?'Ziekteprofiel':'Disease profile'}}</h3><label>{{nl?'Dominante route':'Dominant route'}}<select v-model="p.route"><option v-for="item in routes" :key="item.id" :value="item.id">{{item[nl?'nl':'en']}}</option></select></label><label>R₀ <input v-model.number="p.r0" type="range" min=".2" max="7" step=".1"><output>{{p.r0.toFixed(1)}}</output></label><label>{{nl?'Transmissie vóór symptomen':'Pre-symptomatic transmission'}}<input v-model.number="p.presymptomatic" type="range" min="0" max="80"><output>{{p.presymptomatic}}%</output></label><label>{{nl?'Ernst':'Severity'}}<input v-model.number="p.severity" type="range" min="0" max="100"><output>{{p.severity}}</output></label><label>{{nl?'IC-behoefte':'ICU need'}}<input v-model.number="p.icuNeed" type="range" min="0" max="100"><output>{{p.icuNeed}}</output></label><label>{{nl?'Druk op zorgcapaciteit':'Healthcare pressure'}}<input v-model.number="p.capacityPressure" type="range" min="0" max="100"><output>{{p.capacityPressure}}%</output></label></section>
    <section><h3>2 · {{nl?'Beschikbaar en bekend':'Available and known'}}</h3><div class="checks"><label><input v-model="p.diagnostics" type="checkbox">{{nl?'Bruikbare diagnostiek':'Usable diagnostics'}}</label><label><input v-model="p.vaccine" type="checkbox">{{nl?'Passend vaccin':'Matching vaccine'}}</label><label><input v-model="p.treatment" type="checkbox">{{nl?'Effectieve behandeling':'Effective treatment'}}</label></div><label>{{nl?'Algemene onzekerheid':'Overall uncertainty'}}<input v-model.number="p.uncertainty" type="range" min="0" max="100"><output>{{p.uncertainty}}%</output></label></section>
    <details><summary>3 · {{nl?'Doelen wegen':'Weight objectives'}}</summary><p>{{nl?'Waarden worden relatief genormaliseerd; ze hoeven niet tot 100 op te tellen.':'Values are normalised relative to one another; they need not add to 100.'}}</p><label>{{nl?'Levens en gezondheid':'Lives and health'}}<input v-model.number="p.lives" type="range" min="0" max="100"><output>{{Math.round(weight('lives')*100)}}%</output></label><label>{{nl?'Zorg toegankelijk houden':'Maintain healthcare access'}}<input v-model.number="p.capacity" type="range" min="0" max="100"><output>{{Math.round(weight('capacity')*100)}}%</output></label><label>{{nl?'Transmissie verminderen':'Reduce transmission'}}<input v-model.number="p.transmission" type="range" min="0" max="100"><output>{{Math.round(weight('transmission')*100)}}%</output></label><label>{{nl?'Ontwrichting beperken':'Limit disruption'}}<input v-model.number="p.society" type="range" min="0" max="100"><output>{{Math.round(weight('society')*100)}}%</output></label></details>
   </div>
   <div class="results"><div class="profile"><span>{{nl?'DOMINANTE ROUTE':'DOMINANT ROUTE'}}</span><strong>{{routeLabel}}</strong><span>{{nl?'ONZEKERHEID':'UNCERTAINTY'}}</span><strong>{{p.uncertainty<34?(nl?'laag':'low'):p.uncertainty<67?(nl?'middel':'moderate'):(nl?'hoog':'high')}}</strong></div><h3>{{nl?'Indicatieve prioriteiten':'Indicative priorities'}}</h3><ol><li v-for="(item,index) in ranked.slice(0,6)" :key="item.id"><span>{{index+1}}</span><div><strong>{{item[nl?'nl':'en']}}</strong><small>{{item.reasons.join(' · ')|| (nl?'brede ondersteunende waarde':'broad supporting value')}}</small></div><div class="score"><i :style="{width:`${Math.max(4,Math.min(100,35+item.score*16))}%`}"></i><small>{{nl?'vertrouwen':'confidence'}} {{Math.round(item.confidence*100)}}%</small></div></li></ol><p class="why"><strong>{{nl?'Waarom kan de rangorde omslaan?':'Why can the ranking change?'}}</strong> {{nl?'Route-overeenkomst, vroege transmissie, zorgdruk en beschikbaarheid veranderen de verwachte baten. De gewichten veranderen vervolgens hoeveel maatschappelijke belasting acceptabel lijkt.':'Route match, early transmission, healthcare pressure and availability change expected benefits. The weights then change how much societal burden appears acceptable.'}}</p></div>
  </div>
  <footer><p>{{nl?'Rekenmodel v0.1. Scores zijn transparante scenarioaannames, geen gekalibreerde effectschattingen. Een echte toepassing vereist pathogeenspecifiek bewijs, lokale data, verdelingseffecten, juridische en ethische toetsing, onzekerheidsanalyse en periodieke herbeoordeling.':'Model v0.1. Scores are transparent scenario assumptions, not calibrated effect estimates. Real use requires pathogen-specific evidence, local data, distributional effects, legal and ethical review, uncertainty analysis and periodic reassessment.'}}</p></footer>
 </section>
</template>

<style scoped>
.response-model{margin:4rem calc((780px - min(1180px,100vw - 48px))/2);width:min(1180px,calc(100vw - 48px));padding:42px;background:#edf2f0;border:1px solid var(--line);border-radius:4px}.response-model header{max-width:830px}.eyebrow{font-size:.7rem;letter-spacing:.13em;font-weight:800;color:var(--accent)}h2{font-size:clamp(2.2rem,4vw,3.7rem);margin:.2rem 0 .7rem}header p:last-child{color:#4f5c58}.presets{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:24px 0}.presets span{color:var(--muted);font-size:.7rem}button{border:1px solid #b9c7c1;background:white;padding:7px 10px;font:inherit;font-size:.68rem;cursor:pointer}button:hover{background:#203b36;color:white}.model-grid{display:grid;grid-template-columns:minmax(330px,.82fr) minmax(0,1.18fr);gap:14px}.controls,.results{background:#fff;border:1px solid #d5ded9}.controls section,.controls details{padding:17px 18px;border-bottom:1px solid #dfe5e1}.controls h3,.results h3{font-family:'DM Sans',sans-serif;font-size:.9rem}.controls label{display:grid;grid-template-columns:1fr 120px 42px;align-items:center;gap:9px;margin-top:12px;font-size:.68rem}.controls select{grid-column:2/4;width:100%;padding:5px;border:1px solid #c6d1cb}.controls input{accent-color:#256d72;min-width:0}.controls output{text-align:right;font-variant-numeric:tabular-nums}.checks{display:grid;gap:8px;margin-top:10px}.checks label{display:flex;margin:0;gap:8px}.controls details summary{cursor:pointer;font-size:.78rem;font-weight:750}.controls details p{font-size:.65rem;color:var(--muted)}.results{padding:18px}.profile{display:grid;grid-template-columns:1fr 1fr;gap:3px;background:#d8e0dc}.profile>*{padding:10px 12px;background:#203b36;color:white}.profile span{color:#bfcac5;font-size:.62rem}.profile strong{font:500 1.05rem 'Newsreader',serif}.results h3{margin:22px 0 9px}.results ol{list-style:none;margin:0;padding:0}.results li{display:grid;grid-template-columns:26px minmax(0,1fr) 135px;gap:10px;align-items:center;padding:10px 0;border-top:1px solid #e2e6e3}.results li>span{display:grid;width:24px;height:24px;border-radius:50%;background:#e8efec;place-items:center;font-size:.65rem;font-weight:800}.results li div{display:grid}.results li strong{font-size:.76rem}.results li small{color:#65726d;font-size:.61rem;line-height:1.35}.score{gap:5px}.score:before{content:'';grid-area:1/1;width:100%;height:6px;background:#e3e8e5}.score i{grid-area:1/1;display:block;height:6px;background:#d55c3c;z-index:1}.score small{text-align:right}.why{margin:18px 0 0;padding:13px;background:#f3f6f4;border-left:3px solid #256d72;font-size:.7rem}footer{margin-top:20px;padding-top:15px;border-top:1px solid #cbd5d0;color:#64716c;font-size:.66rem}@media(max-width:760px){.response-model{margin:3rem calc((780px - (100vw - 32px))/2);width:calc(100vw - 32px);padding:26px 16px}.model-grid{grid-template-columns:1fr}.controls label{grid-template-columns:1fr 105px 38px}.results li{grid-template-columns:24px 1fr}.score{grid-column:2}.profile{grid-template-columns:1fr}}
</style>
